function patch(prog: Rung[], edits: Record<string, string | null>): Rung[] {
  const out: Rung[] = [];
  for (const r of prog) {
    if (!(r.id in edits)) out.push(r);
    else if (edits[r.id] !== null) out.push(parseRung(edits[r.id] as string, r.id));
  }
  return out;
}

