    ctx.fillRect(rx - 7, ry + 2, 14, 5);
    st.pickFx = st.pickFx.filter((p) => now - p.t0 < 900);
    for (const p of st.pickFx) {
      const k = (now - p.t0) / 900;
      ctx.save();
      ctx.globalAlpha = 1 - k;
      ctx.fillStyle = COLORS.box;
      rr(X(p.x) - boxW / 2, by - k * bh * 1.4, boxW, boxH, 3);
      ctx.fill();
      ctx.restore();
