    const tx = bx1 + Math.min(44, w * 0.04);
    const ty = by - bh * 1.7;
    ctx.fillStyle = '#20252e';
    rr(tx - 9, ty - 4, 18, 62, 5);
    ctx.fill();
    const lamps: [string, string][] = [
      ['LAMP_RED', COLORS.red],
      ['LAMP_AMBER', COLORS.amber],
      ['LAMP_GREEN', COLORS.green],
    ];
    lamps.forEach(([n, c], i) => {
