        ctx.stroke();
        ctx.fillStyle = 'rgba(239,68,68,0.08)';
        ctx.fill();
        ctx.font = '700 13px Inter, sans-serif';
        ctx.fillStyle = COLORS.red;
        ctx.textAlign = 'right';
        ctx.fillText(`${st.flash.v.rule} VIOLATED`, x0 + w - pad, y0 + 24);
        ctx.restore();
      }
