    ctx.fillStyle = COLORS.belt;
    rr(bx0 - 8, by, bx1 - bx0 + 16, bh, bh / 2);
    ctx.fill();
    ctx.strokeStyle = COLORS.beltEdge;
    ctx.lineWidth = 1;
    ctx.stroke();
    // tread
    ctx.save();
    rr(bx0 - 8, by, bx1 - bx0 + 16, bh, bh / 2);
    ctx.clip();
    ctx.strokeStyle = COLORS.tread;
