      ctx.moveTo(sx, by - 14);
      ctx.lineTo(sx, by + bh + 14);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = on ? COLORS.amber : '#2b323d';
      ctx.fillRect(sx - 5, by - 22, 10, 8);
