    }

    // robot at the pick position
    const rx = X(3.7);
    const ry = by - bh * 1.15;
    ctx.strokeStyle = '#6b7280';
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(rx + 34, ry - 6);
    ctx.lineTo(rx + 10, ry - 16);
    ctx.lineTo(rx, ry + 2);
