    };
    const c1 = px + pw * 0.25;
    const c2 = px + pw * 0.5;
    const c3 = px + pw * 0.75;
    btn('START', 'START', c1, py - 12, COLORS.green, f?.in.START === 1);
    btn('STOP', 'STOP', c2, py - 12, '#e5e7eb', f?.in.STOP === 1);
