      ['2', 'after 2 s'],
    ])
      this.pickSel.append(h('option', { value: v }, l));
    this.pickSel.value = '1';
    const onAuto = (): void => hnd.setAuto(Number(this.feedSel.value), Number(this.pickSel.value));
    this.feedSel.addEventListener('change', onAuto);
